"""Typed payload models and template compilation for the offline pipeline.

Frames are validated with exact key sets and strict types (no coercion), then
compiled against the shared byte-program Context so every header name/value and
data string becomes a compressed byte sequence with its proper coordinate.
"""
from typing import Any, Dict, List, Literal, Tuple, Union

from pydantic import BaseModel, ConfigDict

from modules.byte_program import MAX


class H3HeaderFrame(BaseModel):
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)
    Type: Literal['headers']
    data_to_transfered: List[Tuple[Any, Any]]
    End_Stream: bool = False


class H3DataFrame(BaseModel):
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)
    Type: Literal['data', 'datagram']
    data_to_transfered: Any
    End_Stream: bool = True


class H3SleepFrame(BaseModel):
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)
    Type: Literal['sleep']
    Time_to_Stop: int


Frame = Union[H3HeaderFrame, H3DataFrame, H3SleepFrame]


class FuzzingPayload(BaseModel):
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)
    test_cases: Dict[str, List[Frame]]


HEADER_KEYS = {'Type', 'headers_kv', 'data_to_transfered', 'End_Stream'}
DATA_KEYS = {'Type', 'data_to_transfered', 'End_Stream'}
SLEEP_KEYS = {'Type', 'Time_to_Stop'}


def compile_cases(cases, context):
    """Compile validated case specs into a typed payload.

    Returns (payload, pause_totals, pair_count) where pause_totals maps case
    name to the sum of its sleep durations and pair_count is the number of
    header pairs carried by case frames.
    """
    data = {}
    pause_totals = {}
    pair_count = 0
    for i, case in enumerate(cases):
        name = case['name']
        out = []
        pause = 0
        for j, frame in enumerate(case['frames']):
            if type(frame) is not dict:
                raise ValueError('frame')
            kind = frame.get('Type')
            if type(kind) is not str:
                raise ValueError('frame type')
            keys = set(frame)
            if kind == 'headers':
                if not keys <= HEADER_KEYS:
                    raise ValueError('frame keys')
                has_kv = 'headers_kv' in frame
                has_list = 'data_to_transfered' in frame
                if has_kv == has_list:
                    raise ValueError('headers frame fields')
                end = frame.get('End_Stream', False)
                if type(end) is not bool:
                    raise ValueError('End_Stream')
                if has_kv:
                    kv = frame['headers_kv']
                    if type(kv) is not dict:
                        raise ValueError('headers_kv')
                    pairs = list(kv.items())
                    for k, v in pairs:
                        if type(k) is not str or type(v) is not str:
                            raise ValueError('header pair')
                else:
                    raw = frame['data_to_transfered']
                    if type(raw) is not list:
                        raise ValueError('header list')
                    pairs = []
                    for item in raw:
                        if type(item) is not list or len(item) != 2:
                            raise ValueError('header pair')
                        k, v = item
                        if type(k) is not str or type(v) is not str:
                            raise ValueError('header pair')
                        pairs.append((k, v))
                if len(pairs) > 128:
                    raise ValueError('header pairs')
                pair_count += len(pairs)
                compiled = []
                for p, (k, v) in enumerate(pairs):
                    compiled.append((context.template(k, f'case/{i}/frame/{j}/h/{p}/n'),
                                     context.template(v, f'case/{i}/frame/{j}/h/{p}/v')))
                out.append(H3HeaderFrame.model_construct(
                    Type='headers', data_to_transfered=compiled, End_Stream=end))
            elif kind in ('data', 'datagram'):
                if not keys <= DATA_KEYS or 'data_to_transfered' not in frame:
                    raise ValueError('frame keys')
                raw = frame['data_to_transfered']
                if type(raw) is not str:
                    raise ValueError('frame data')
                end = frame.get('End_Stream', True)
                if type(end) is not bool:
                    raise ValueError('End_Stream')
                node = context.template(raw, f'case/{i}/frame/{j}/data')
                out.append(H3DataFrame.model_construct(
                    Type=kind, data_to_transfered=node, End_Stream=end))
            elif kind == 'sleep':
                if keys != SLEEP_KEYS:
                    raise ValueError('frame keys')
                stop = frame['Time_to_Stop']
                if type(stop) is not int or not 0 <= stop <= MAX:
                    raise ValueError('Time_to_Stop')
                pause += stop
                out.append(H3SleepFrame.model_construct(
                    Type='sleep', Time_to_Stop=stop))
            else:
                raise ValueError('frame type')
        data[name] = out
        pause_totals[name] = pause
    return FuzzingPayload.model_construct(test_cases=data), pause_totals, pair_count
EOF
